import Foundation

/// Authentication request sent from a client application to the Paspo ID app.
///
/// Serialized as `paspo://sso?...`. The Paspo ID app parses the same structure on its side,
/// which is why this type lives in the shared wire target.
public struct PaspoAuthRequest: Sendable, Equatable {
    /// One-time value generated by the integrator's backend.
    public let nonce: String
    /// Client's ephemeral X.509 P-256 public key.
    public let clientPublicKeyDER: Data
    /// Bundle identifier of the calling application.
    public let bundleID: String
    /// Requested profile data.
    public let scope: PaspoScope
    /// Absolute URL Paspo ID opens to deliver the result.
    public let redirectURL: URL
    /// Opaque per-request identifier, echoed back in the callback.
    public let state: String
    /// Nonce stored before an App Store redirect, for install attribution.
    public let referralNonce: String?
    /// Contract version.
    public let version: Int

    public init(
        nonce: String,
        clientPublicKeyDER: Data,
        bundleID: String,
        scope: PaspoScope,
        redirectURL: URL,
        state: String,
        referralNonce: String? = nil,
        version: Int = PaspoSSOConstants.contractVersion
    ) {
        self.nonce = nonce
        self.clientPublicKeyDER = clientPublicKeyDER
        self.bundleID = bundleID
        self.scope = scope
        self.redirectURL = redirectURL
        self.state = state
        self.referralNonce = referralNonce
        self.version = version
    }

    /// Builds the `paspo://sso` URL to open.
    public func makeURL() -> URL? {
        var components = URLComponents()
        components.scheme = PaspoSSOConstants.paspoScheme
        components.host = PaspoSSOConstants.ssoHost

        typealias Key = PaspoSSOConstants.RequestParameter
        var items: [URLQueryItem] = [
            URLQueryItem(name: Key.nonce, value: nonce),
            URLQueryItem(name: Key.publicKey, value: Base64URL.encode(clientPublicKeyDER)),
            URLQueryItem(name: Key.bundleID, value: bundleID),
            URLQueryItem(name: Key.scope, value: scope.key),
            URLQueryItem(name: Key.redirect, value: Base64URL.encode(Data(redirectURL.absoluteString.utf8))),
            URLQueryItem(name: Key.state, value: state),
            URLQueryItem(name: Key.version, value: String(version)),
        ]
        if let referralNonce, referralNonce.isEmpty == false {
            items.append(URLQueryItem(name: Key.referralNonce, value: referralNonce))
        }
        components.queryItems = items
        return components.url
    }

    /// Parses a `paspo://sso` URL. Returns `nil` when the URL is not an SSO request or a
    /// required parameter is missing or malformed.
    public static func parse(url: URL) -> PaspoAuthRequest? {
        guard let components = URLComponents(url: url, resolvingAgainstBaseURL: false),
              components.scheme == PaspoSSOConstants.paspoScheme,
              components.host == PaspoSSOConstants.ssoHost
        else { return nil }

        typealias Key = PaspoSSOConstants.RequestParameter
        let query = components.queryItems ?? []
        func value(_ name: String) -> String? {
            guard let value = query.first(where: { $0.name == name })?.value, value.isEmpty == false else { return nil }
            return value
        }

        guard let nonce = value(Key.nonce),
              let publicKey = value(Key.publicKey).flatMap(Base64URL.decode),
              let bundleID = value(Key.bundleID),
              let scope = value(Key.scope).flatMap(PaspoScope.init(key:)),
              let redirectString = value(Key.redirect)
              .flatMap(Base64URL.decode)
              .flatMap({ String(data: $0, encoding: .utf8) }),
              let redirectURL = URL(string: redirectString),
              let state = value(Key.state)
        else { return nil }

        return PaspoAuthRequest(
            nonce: nonce,
            clientPublicKeyDER: publicKey,
            bundleID: bundleID,
            scope: scope,
            redirectURL: redirectURL,
            state: state,
            referralNonce: value(Key.referralNonce),
            version: value(Key.version).flatMap(Int.init) ?? PaspoSSOConstants.contractVersion
        )
    }
}
